-- Frozen100-row feed from53c04b1 before correlation planning boundaries.
WITH matched AS(SELECT  c.id,c.manga_id,c.published_at AS sort_value,''::text AS sort_text FROM platform.catalog_chapters c JOIN platform.catalog_manga m ON m.id=c.manga_id LEFT JOIN platform.catalog_chapter_counters s ON s.chapter_id=c.id WHERE c.deleted_at IS NULL AND m.deleted_at IS NULL AND m.state='published' AND platform.protocol_source_is_visible(c.protocol_event_id) AND c.language=ANY($1) AND m.content_rating=ANY($2) AND m.protocol_source_visible AND platform.protocol_source_is_visible(m.protocol_series_id) ),selected AS MATERIALIZED(SELECT * FROM matched ORDER BY sort_value DESC NULLS LAST,sort_text DESC,id LIMIT $3 OFFSET $4),parent_dtos AS MATERIALIZED(SELECT manga_id,platform.catalog_manga_json(manga_id) AS value FROM(SELECT DISTINCT manga_id FROM selected)ids),group_dtos AS MATERIALIZED(SELECT g.id,platform.catalog_group_json(g.id) AS value FROM platform.catalog_groups g JOIN(SELECT DISTINCT cg.group_id FROM platform.catalog_chapter_groups cg JOIN selected ON selected.id=cg.chapter_id)ids ON ids.group_id=g.id WHERE g.deleted_at IS NULL AND platform.protocol_group_is_visible(g.id)) SELECT jsonb_build_object('total',(SELECT count(*) FROM matched),'limit',100,'page',1,'data',COALESCE((SELECT jsonb_agg(platform.catalog_chapter_json(selected.id,parent_dtos.value,COALESCE((SELECT jsonb_agg(group_dtos.value ORDER BY cg.group_id) FROM platform.catalog_chapter_groups cg JOIN group_dtos ON group_dtos.id=cg.group_id WHERE cg.chapter_id=selected.id),'[]'::jsonb)) || jsonb_build_object('_sort_value',sort_value,'_sort_text',sort_text) ORDER BY sort_value DESC NULLS LAST,sort_text DESC,selected.id) FROM selected JOIN parent_dtos ON parent_dtos.manga_id=selected.manga_id),'[]'::jsonb),'map',jsonb_build_object('manga',COALESCE((SELECT jsonb_object_agg(manga_id,value) FROM parent_dtos),'{}'::jsonb)));
